__global__ static void moe_down_sorted_p2_qwarp32_kernel(
        float *down_out,
        const char *down_base,
        const cuda_block_q8_K *midq,
        const uint32_t *sorted_pairs,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t midq_blocks,
        uint32_t out_dim,
        uint32_t n_expert,
        uint32_t pair_count) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t pair_lane = (threadIdx.x >> 3u) & 1u;
    uint32_t row = blockIdx.x * 16u + (threadIdx.x >> 4u);
    uint32_t sorted_idx = blockIdx.y * 2u + pair_lane;
    if (row >= out_dim || sorted_idx >= pair_count) return;
    uint32_t pair = sorted_pairs[sorted_idx];
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const cuda_block_q8_K *xq = midq + (uint64_t)pair * midq_blocks;
    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 8u) acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
    acc = quarter_warp_sum_f32(acc, lane);
    if (lane == 0) down_out[(uint64_t)pair * out_dim + row] = acc;
}

__global__ static void moe_sum_kernel(float *out, const float *down, uint32_t out_dim, uint32_t n_expert, uint32_t n_tokens) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    uint32_t tok = gid / out_dim;
    uint32_t row = gid - (uint64_t)tok * out_dim;
    float acc = 0.0f;
    for (uint32_t e = 0; e < n_expert; e++) acc += down[((uint64_t)tok * n_expert + e) * out_dim + row];
    out[gid] = acc;
}

__device__ static float dev_iq2_xxs_dot_f32(const cuda_block_iq2_xxs *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_iq2_xxs *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const uint16_t *q2 = xb->qs;
        const float *xf = x + (uint64_t)b * CUDA_QK_K;
        for (uint32_t ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
            const uint32_t aux_g = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
            const uint32_t aux_s = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
            q2 += 4;
            const float dl = d * (0.5f + (float)(aux_s >> 28)) * 0.25f;
            const uint8_t grids[4] = {
                (uint8_t)(aux_g & 0xffu),
                (uint8_t)((aux_g >> 8) & 0xffu),
                (uint8_t)((aux_g >> 16) & 0xffu),
                (uint8_t)((aux_g >> 24) & 0xffu),
            };
            for (uint32_t half = 0; half < 2; half++) {
                for (uint32_t g = 0; g < 2; g++) {
                    const uint32_t gi = half * 2 + g;
                    const uint64_t grid = cuda_iq2xxs_grid[grids[gi]];
                    const uint8_t signs = cuda_ksigns_iq2xs[(aux_s >> (14u * half + 7u * g)) & 127u];
                    for (uint32_t i = 0; i < 8; i++) {
                        float w = (float)((grid >> (8u * i)) & 0xffu);
                        if (signs & (1u << i)) w = -w;
                        acc += dl * w * xf[ib32 * 32u + half * 16u + g * 8u + i];
                    }
                }
            }
        }
    }
    return acc;
}

__device__ static float dev_q2_K_dot_f32(const cuda_block_q2_K *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_q2_K *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const float dmin = dev_f16_to_f32(xb->dmin);
        for (uint32_t il = 0; il < 16; il++) {
            const uint32_t chunk = il / 8u;
            const uint32_t pair = il & 1u;
            const uint32_t shift = ((il / 2u) & 3u) * 2u;
            const uint8_t sc = xb->scales[il];
            const float dl = d * (float)(sc & 0x0fu);
            const float ml = dmin * (float)(sc >> 4);
            const uint8_t *q = xb->qs + 32u * chunk + 16u * pair;
            const float *xf = x + (uint64_t)b * CUDA_QK_K + chunk * 128u + ((il % 8u) / 2u) * 32u + pair * 16u;
            for (uint32_t i = 0; i < 16; i++) {
                const float w = dl * (float)((q[i] >> shift) & 3u) - ml;
                acc += w * xf[i];
            }
        }
    }
    return acc;
}

__global__ static void moe_gate_up_mid_f32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const float *x,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= expert_mid_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    uint32_t expert = (uint32_t)expert_i;
    const uint32_t nb = expert_in_dim / CUDA_QK_K;
    const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const float *xr = x + (uint64_t)tok * expert_in_dim;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) {
        gate += dev_iq2_xxs_dot_f32(gr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
        up += dev_iq2_xxs_dot_f32(ur + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    }
    __shared__ float partial_gate[256];
    __shared__ float partial_up[256];
    partial_gate[threadIdx.x] = gate;
    partial_up[threadIdx.x] = up;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            partial_gate[threadIdx.x] += partial_gate[threadIdx.x + stride];
            partial_up[threadIdx.x] += partial_up[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        gate = partial_gate[0];
        up = partial_up[0];
        if (clamp > 1.0e-6f) {
            if (gate > clamp) gate = clamp;
            if (up > clamp) up = clamp;
            if (up < -clamp) up = -clamp;
        }
        const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
        gate_out[off] = gate;
        up_out[off] = up;
        mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
    }
}

__global__ static void moe_down_f32_kernel(
        float *down_out,
        const char *down_base,
        const float *mid,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        uint32_t n_expert) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= out_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const uint32_t nb = expert_mid_dim / CUDA_QK_K;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const float *xr = mid + (uint64_t)pair * expert_mid_dim;
    float acc = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) acc += dev_q2_K_dot_f32(wr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) down_out[(uint64_t)pair * out_dim + row] = partial[0];
}

/* ---- Selected-expert MoE load (G7): stream/gather ONLY the routed experts ----
 * ds4-win's routed_moe fetched the whole 256-expert gate/up/down block per layer
 * even though decode routes top-6. In the beyond-window streaming regime that is
 * ~42x wasted SSD->VRAM traffic and the source of the eviction thrash. Here we
 * read the router's selected indices to the host, dedupe them, fetch each routed
 * expert through the existing per-offset LRU fd-cache (cross-token reuse for free),
 * gather them into a compact contiguous VRAM buffer, and remap `selected` to
 * compact slots so the unchanged MoE kernels touch only the routed experts. */
struct cuda_moe_gather {
    char *gate; uint64_t gate_cap;
    char *up;   uint64_t up_cap;
    char *down; uint64_t down_cap;
    int32_t *slot; uint64_t slot_cap;
    ds4_gpu_tensor slot_tensor;
    std::vector<int32_t> h_sel;
    std::vector<float> h_weights;
    std::vector<int32_t> h_expert_to_slot;
    std::vector<int32_t> h_compact_ids;
    std::vector<int32_t> h_slot_ids;
    struct span {
        char *dst;
        uint64_t offset;
        uint64_t bytes;
        char *mirror;
        uint32_t arena_entry;
        uint8_t arena_part;
    };
    std::vector<span> h_spans;
    std::vector<int32_t> h_cache_slots;
    std::vector<uint8_t> h_cache_claimed;
    std::vector<uint32_t> h_cache_admission_compact;
    std::vector<uint32_t> h_cache_admission_slots;
    std::vector<uint8_t> h_cache_admission_evicted;
    std::vector<float> h_compact_mass;
    std::vector<uint8_t> h_arena_resident;
};
static cuda_moe_gather g_moe_gather;

struct cuda_moe_selected_prepared {
    const void *model_map;
    const void *selected_ptr;
    uint64_t gate_offset;
    uint64_t up_offset;
    uint64_t down_offset;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    uint32_t n_expert;
    uint32_t n_tokens;
    int full;
    int valid;
};
static cuda_moe_selected_prepared g_moe_selected_prepared;

struct cuda_moe_last_selected {
    uint64_t gate_offset;
    uint32_t count;
    int32_t ids[256];
    int valid;
};
static cuda_moe_last_selected g_moe_last_selected;

enum cuda_moe_cache_slot_state : uint8_t {
    CUDA_MOE_CACHE_EMPTY = 0,
    CUDA_MOE_CACHE_VALID = 1,
    CUDA_MOE_CACHE_LOADING = 2,
};

struct cuda_moe_cache_key {
    uint64_t gate_src;
    uint64_t up_src;
    uint64_t down_src;
};

struct cuda_moe_cache_slot {
    cuda_moe_cache_key key;
    uint64_t layer_key;
    uint64_t age;
    uint8_t layer_owned;
    cuda_moe_cache_slot_state state;
};

struct cuda_moe_expert_cache {
    char *gate;
    char *up;
    char *down;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    uint64_t tick;
    uint64_t calls;
    uint64_t hits;
    uint64_t misses;
    uint64_t admissions;
    uint64_t evictions;
    uint64_t direct_loads;
    uint32_t requested;
    uint32_t capacity;
    uint32_t count;
    std::vector<cuda_moe_cache_slot> slots;
};
static cuda_moe_expert_cache g_moe_expert_cache;

static uint32_t cuda_moe_expert_cache_requested(void) {
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_N");
    if (!env || !env[0]) return 0;
    char *end = NULL;
    errno = 0;
    const unsigned long v = strtoul(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0') return 0;
    return v > 512ul ? 512u : (uint32_t)v;
}

static int cuda_moe_expert_cache_layer_top1(void) {
    const char *env = getenv("DS4_CUDA_MOE_CACHE_POLICY");
    return env && strcmp(env, "layer-top1") == 0;
}

static uint64_t cuda_moe_expert_cache_stats_interval(void) {
    if (getenv("DS4_CUDA_MOE_CACHE_STATS") == NULL) return 0;
    const char *env = getenv("DS4_CUDA_MOE_CACHE_STATS_INTERVAL");
    if (!env || !env[0]) return 128;
    char *end = NULL;
    errno = 0;
    const unsigned long long v = strtoull(env, &end, 10);
    while (end && (*end == ' ' || *end == '\t')) end++;
    if (end == env || errno != 0 || !end || *end != '\0' || v == 0) return 128;
    return (uint64_t)v;
}

static uint64_t cuda_moe_expert_cache_reserve_bytes(void) {
    double gb = 0.5;
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_RESERVE_GB");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        const double v = strtod(env, &end);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end != env && errno == 0 && end && *end == '\0' && v >= 0.0) gb = v;
    }
    const double bytes = gb * 1073741824.0;
    return bytes >= (double)UINT64_MAX ? UINT64_MAX : (uint64_t)bytes;
}

static void cuda_moe_expert_cache_invalidate(void) {
    for (cuda_moe_cache_slot &slot : g_moe_expert_cache.slots) {
        slot.state = CUDA_MOE_CACHE_EMPTY;
        slot.age = 0;
        slot.layer_key = 0;
        slot.layer_owned = 0;
    }
    g_moe_expert_cache.tick = 0;
    g_moe_expert_cache.count = 0;
}

static void cuda_moe_expert_cache_release(void) {
    if (g_moe_expert_cache.gate) (void)cudaFree(g_moe_expert_cache.gate);
    if (g_moe_expert_cache.up) (void)cudaFree(g_moe_expert_cache.up);
    if (g_moe_expert_cache.down) (void)cudaFree(g_moe_expert_cache.down);
    g_moe_expert_cache.gate = NULL;
    g_moe_expert_cache.up = NULL;
    g_moe_expert_cache.down = NULL;
    g_moe_expert_cache.gate_expert_bytes = 0;
    g_moe_expert_cache.down_expert_bytes = 0;
    g_moe_expert_cache.tick = 0;
    g_moe_expert_cache.calls = 0;
    g_moe_expert_cache.hits = 0;
    g_moe_expert_cache.misses = 0;
    g_moe_expert_cache.admissions = 0;
    g_moe_expert_cache.evictions = 0;
    g_moe_expert_cache.direct_loads = 0;
    g_moe_expert_cache.requested = 0;
    g_moe_expert_cache.capacity = 0;
    g_moe_expert_cache.count = 0;
    g_moe_expert_cache.slots.clear();
}

static void cuda_moe_gather_release(void) {
    g_moe_selected_prepared.valid = 0;
    g_moe_last_selected.valid = 0;
    if (g_moe_gather.gate) (void)cudaFree(g_moe_gather.gate);
    if (g_moe_gather.up) (void)cudaFree(g_moe_gather.up);
    if (g_moe_gather.down) (void)cudaFree(g_moe_gather.down);
    if (g_moe_gather.slot) (void)cudaFree(g_moe_gather.slot);
    g_moe_gather.gate = NULL;
    g_moe_gather.up = NULL;
    g_moe_gather.down = NULL;
    g_moe_gather.slot = NULL;
    g_moe_gather.gate_cap = 0;
    g_moe_gather.up_cap = 0;
    g_moe_gather.down_cap = 0;
    g_moe_gather.slot_cap = 0;
    g_moe_gather.slot_tensor.ptr = NULL;
    g_moe_gather.slot_tensor.bytes = 0;
    g_moe_gather.slot_tensor.owner = 0;
    g_moe_gather.h_sel.clear();
    g_moe_gather.h_weights.clear();
    g_moe_gather.h_expert_to_slot.clear();
    g_moe_gather.h_compact_ids.clear();
    g_moe_gather.h_slot_ids.clear();
    g_moe_gather.h_spans.clear();
    g_moe_gather.h_cache_slots.clear();
    g_moe_gather.h_cache_claimed.clear();
    g_moe_gather.h_cache_admission_compact.clear();
    g_moe_gather.h_cache_admission_slots.clear();
    g_moe_gather.h_cache_admission_evicted.clear();
    g_moe_gather.h_compact_mass.clear();
    g_moe_gather.h_arena_resident.clear();
}

static cuda_moe_expert_cache *cuda_moe_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const uint32_t requested = cuda_moe_expert_cache_requested();
    if (requested == 0) {
        if (g_moe_expert_cache.capacity != 0) cuda_moe_expert_cache_release();
        return NULL;
    }
    if (gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return NULL;
    }
    if (g_moe_expert_cache.capacity != 0 &&
        g_moe_expert_cache.requested == requested &&
        g_moe_expert_cache.gate_expert_bytes == gate_expert_bytes &&
        g_moe_expert_cache.down_expert_bytes == down_expert_bytes) {
        return &g_moe_expert_cache;
    }
    cuda_moe_expert_cache_release();

    const uint64_t per_expert = gate_expert_bytes * 2ull + down_expert_bytes;
    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA resident expert cache memory query failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    uint64_t reserve = cuda_moe_expert_cache_reserve_bytes();
    if (total_b != 0 && reserve > (uint64_t)total_b / 2ull) reserve = (uint64_t)total_b / 2ull;
    uint32_t cap = 0;
    if ((uint64_t)free_b > reserve) {
        const uint64_t max_slots = ((uint64_t)free_b - reserve) / per_expert;
        cap = max_slots < requested ? (uint32_t)max_slots : requested;
    }
    if (cap == 0) {
        fprintf(stderr,
                "ds4: CUDA resident expert cache disabled: free %.2f GiB <= reserve %.2f GiB\n",
                (double)free_b / 1073741824.0, (double)reserve / 1073741824.0);
        return NULL;
    }

    while (cap != 0) {
        void *gate = NULL;
        void *up = NULL;
        void *down = NULL;
        err = cudaMalloc(&gate, (size_t)((uint64_t)cap * gate_expert_bytes));
        if (err == cudaSuccess) err = cudaMalloc(&up, (size_t)((uint64_t)cap * gate_expert_bytes));
        if (err == cudaSuccess) err = cudaMalloc(&down, (size_t)((uint64_t)cap * down_expert_bytes));
        if (err == cudaSuccess) {
            try {
                g_moe_expert_cache.slots.resize(cap);
            } catch (...) {
                err = cudaErrorMemoryAllocation;
            }
        }
        if (err == cudaSuccess) {
            g_moe_expert_cache.gate = (char *)gate;
            g_moe_expert_cache.up = (char *)up;
            g_moe_expert_cache.down = (char *)down;
            g_moe_expert_cache.gate_expert_bytes = gate_expert_bytes;
            g_moe_expert_cache.down_expert_bytes = down_expert_bytes;
            g_moe_expert_cache.requested = requested;
            g_moe_expert_cache.capacity = cap;
            cuda_moe_expert_cache_invalidate();
            fprintf(stderr,
                    "ds4: CUDA resident expert cache ready: %u/%u experts, %.2f MiB/expert, %.2f GiB total\n",
                    cap, requested, (double)per_expert / 1048576.0,
                    (double)((uint64_t)cap * per_expert) / 1073741824.0);
            return &g_moe_expert_cache;
        }
        const char *why = cudaGetErrorString(err);
        (void)cudaGetLastError();
        g_moe_expert_cache.slots.clear();
        if (gate) (void)cudaFree(gate);
        if (up) (void)cudaFree(up);
        if (down) (void)cudaFree(down);
        const uint32_t release = (cap + 9u) / 10u;
        const uint32_t next = cap > release ? cap - release : 0;
        fprintf(stderr,
                "ds4: CUDA resident expert cache allocation failed at %u slots: %s; retry=%u\n",
                cap, why, next);
        cap = next;
    }
    cuda_moe_expert_cache_release();
    return NULL;
}

static int cuda_moe_expert_cache_find(
        cuda_moe_expert_cache *cache,
        const cuda_moe_cache_key &key) {
    if (!cache) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (slot.state == CUDA_MOE_CACHE_VALID &&
            slot.key.gate_src == key.gate_src &&
            slot.key.up_src == key.up_src &&
            slot.key.down_src == key.down_src) {
            return (int)i;
        }
    }
    return -1;
}

static int cuda_moe_expert_cache_lru_slot(
        cuda_moe_expert_cache *cache,
        const std::vector<uint8_t> &claimed) {
    if (!cache || claimed.size() < cache->capacity) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!claimed[i] && cache->slots[i].state == CUDA_MOE_CACHE_EMPTY) return (int)i;
    }
    int best = -1;
    uint64_t best_age = UINT64_MAX;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_moe_cache_slot &slot = cache->slots[i];
        if (claimed[i] || slot.state != CUDA_MOE_CACHE_VALID) continue;
        if (slot.age < best_age) {
            best = (int)i;
            best_age = slot.age;
        }
    }
    return best;
}

static int cuda_moe_expert_cache_copy_to_compact_async(
        cuda_moe_expert_cache *cache,
        uint32_t cache_slot,
        uint32_t compact_slot) {
    const uint64_t gate_src = (uint64_t)cache_slot * cache->gate_expert_bytes;
    const uint64_t gate_dst = (uint64_t)compact_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)cache_slot * cache->down_expert_bytes;
    const uint64_t down_dst = (uint64_t)compact_slot * cache->down_expert_bytes;
    return cudaMemcpyAsync(g_moe_gather.gate + gate_dst, cache->gate + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.up + gate_dst, cache->up + gate_src,
                           (size_t)cache->gate_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess &&
           cudaMemcpyAsync(g_moe_gather.down + down_dst, cache->down + down_src,
                           (size_t)cache->down_expert_bytes, cudaMemcpyDeviceToDevice,
                           g_model_upload_stream) == cudaSuccess;
}

/* Selected-load profiling accumulators (DS4_CUDA_SEL_PROFILE). */
static uint64_t g_sel_prof_calls;
static uint64_t g_sel_prof_experts;
static double g_sel_prof_fetch_s;

static int cuda_model_range_in_window(const void *model_map, uint64_t offset, uint64_t bytes) {
    return g_model_window_bytes && model_map == g_model_host_base && g_model_device_base &&
           offset + bytes <= g_model_window_bytes;
}

/* Persistent staging rotation so consecutive span uploads pipeline (pread of the
 * next tensor overlaps the H2D copy of the previous one). */
static uint64_t g_stream_span_idx = 0;

/* Stream `bytes` from the model file at `offset` DIRECTLY into a caller-owned
 * device buffer `dst`, async on the upload stream via the pinned staging pool.
 * No cudaMalloc / eviction / range-cache: this is the fast path for MoE experts
 * (cross-token reuse ~0, so the per-expert VRAM cache's malloc/evict churn --
 * ~40 ms/expert on WDDM, disk-independent -- is pure overhead). The caller MUST
 * cudaStreamSynchronize(g_model_upload_stream) before the data is read elsewhere. */
static int cuda_model_stream_span_into(
        char *dst,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    if (!g_model_file_valid || bytes == 0 || !dst) return 0;
    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) return 0;
    uint64_t copied = 0;
    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = g_stream_span_idx % 4u;
        if (g_stream_span_idx >= 4u) {
            if (cudaEventSynchronize(g_model_stage_event[bi]) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        }
        const char *payload = NULL;
        if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes, offset + copied, n, &payload)) return 0;
        if (mirror) {
            memcpy(mirror + copied, payload, (size_t)n);
            if (memcmp(mirror + copied, payload, (size_t)n) != 0) return 0;
        }
        if (cudaMemcpyAsync(dst + copied, payload, (size_t)n, cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        if (cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
        cuda_model_drop_file_pages(offset + copied, n);
        copied += n;
        g_stream_span_idx++;
    }
    return 1;
}

#ifdef _WIN32
static uint32_t cuda_moe_io_queue_depth(void) {
    uint32_t qd = 1;
    const char *env = getenv("DS4_CUDA_MOE_IO_QD");
    if (env && env[0]) {
        char *end = NULL;
        const unsigned long v = strtoul(env, &end, 10);
        if (end != env && v > 0) qd = (uint32_t)v;
    }
    if (qd > 4u) qd = 4u;
    return qd;
}

static int cuda_moe_io_events_ensure(void) {
    for (uint32_t i = 0; i < 4u; i++) {
        if (g_moe_io_event[i]) continue;
        g_moe_io_event[i] = CreateEventW(NULL, TRUE, FALSE, NULL);
        if (!g_moe_io_event[i]) {
            fprintf(stderr, "ds4: CUDA MoE overlapped I/O event creation failed: %lu\n",
                    (unsigned long)GetLastError());
            return 0;
        }
    }
    return 1;
}

static void cuda_moe_io_cancel_pending(const int pending[4], uint32_t count) {
    for (uint32_t i = 0; i < count; i++) {
        if (pending[i]) (void)CancelIoEx(g_model_file.h, &g_moe_io_ov[i]);
    }
    for (uint32_t i = 0; i < count; i++) {
        if (!pending[i]) continue;
        DWORD ignored = 0;
        (void)GetOverlappedResult(g_model_file.h, &g_moe_io_ov[i], &ignored, TRUE);
    }
}

/* Batch selected-expert file spans through the existing pinned staging ring.
 * ReadFile operations are submitted concurrently; completed buffers are then
 * uploaded on the existing nonblocking CUDA stream. The caller retains the
 * layer-level upload sync, so this path changes only host I/O concurrency. */
static int cuda_moe_fill_spans_overlapped(
        const void *model_map,
        const std::vector<cuda_moe_gather::span> &spans,
        uint32_t qd) {
    if (qd < 2u || qd > 4u || !g_model_file_valid) return 0;
    const uint64_t stage_bytes = cuda_model_copy_chunk_bytes() +
        (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes) || !cuda_moe_io_events_ensure()) return 0;

    size_t base = 0;
    while (base < spans.size()) {
        const uint32_t count = (uint32_t)((spans.size() - base < qd) ?
            spans.size() - base : qd);
        int pending[4] = {0, 0, 0, 0};

        for (uint32_t i = 0; i < count; i++) {
            const cuda_moe_gather::span &s = spans[base + i];
            if (cuda_model_range_in_window(model_map, s.offset, s.bytes)) {
                const char *src = g_model_device_base + s.offset;
                if (s.mirror) {
                    memcpy(s.mirror,
                           (const char *)model_map + s.offset,
                           (size_t)s.bytes);
                    if (memcmp(s.mirror,
                               (const char *)model_map + s.offset,
                               (size_t)s.bytes) != 0) {
                        cuda_moe_io_cancel_pending(pending, count);
                        return 0;
                    }
                    cuda_dynamic_arena_observer_mirror_done(
                        s.arena_entry, s.arena_part, s.bytes);
                }
                if (cudaMemcpyAsync(s.dst, src, (size_t)s.bytes, cudaMemcpyDefault,
                                    g_model_upload_stream) != cudaSuccess) {
                    (void)cudaGetLastError();
                    cuda_moe_io_cancel_pending(pending, count);
                    return 0;
                }
                continue;
            }
            if (s.bytes == 0 || s.bytes > g_model_stage_bytes || s.bytes > 0xffffffffull) {
                cuda_moe_io_cancel_pending(pending, count);
                return 0;
            }
            if (g_moe_io_stage_used[i]) {
                if (cudaEventSynchronize(g_model_stage_event[i]) != cudaSuccess) {
                    (void)cudaGetLastError();
                    cuda_moe_io_cancel_pending(pending, count);
                    return 0;
                }
            }

            OVERLAPPED &ov = g_moe_io_ov[i];
            memset(&ov, 0, sizeof(ov));
            ov.Offset = (DWORD)(s.offset & 0xffffffffu);
            ov.OffsetHigh = (DWORD)(s.offset >> 32);
            ov.hEvent = g_moe_io_event[i];
            (void)ResetEvent(ov.hEvent);
            const BOOL started = ReadFile(g_model_file.h, g_model_stage[i],
                                          (DWORD)s.bytes, NULL, &ov);
            if (!started && GetLastError() != ERROR_IO_PENDING) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read submit failed at %llu: %lu\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError());
                cuda_moe_io_cancel_pending(pending, count);
                return 0;
            }
            pending[i] = 1;
        }

        for (uint32_t i = 0; i < count; i++) {
            if (!pending[i]) continue;
            const cuda_moe_gather::span &s = spans[base + i];
            DWORD got = 0;
            if (!GetOverlappedResult(g_model_file.h, &g_moe_io_ov[i], &got, TRUE) ||
                got != (DWORD)s.bytes) {
                fprintf(stderr, "ds4: CUDA MoE overlapped read completion failed at %llu: %lu (%lu/%llu bytes)\n",
                        (unsigned long long)s.offset, (unsigned long)GetLastError(),
                        (unsigned long)got, (unsigned long long)s.bytes);
                cuda_moe_io_cancel_pending(pending, count);
                return 0;
            }
            pending[i] = 0;
            if (s.mirror) {
                memcpy(s.mirror, g_model_stage[i], (size_t)s.bytes);
                if (memcmp(s.mirror, g_model_stage[i],
                           (size_t)s.bytes) != 0) {
                    cuda_moe_io_cancel_pending(pending, count);
                    return 0;
                }
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
            if (cudaMemcpyAsync(s.dst, g_model_stage[i], (size_t)s.bytes,
                                cudaMemcpyHostToDevice, g_model_upload_stream) != cudaSuccess ||
                cudaEventRecord(g_model_stage_event[i], g_model_upload_stream) != cudaSuccess) {
                (void)cudaGetLastError();
                cuda_moe_io_cancel_pending(pending, count);
                return 0;
            }
            g_moe_io_stage_used[i] = 1;
            cuda_model_drop_file_pages(s.offset, s.bytes);
        }
        base += count;
    }
    static int notice_printed = 0;
    if (!notice_printed) {
        fprintf(stderr, "ds4: CUDA MoE overlapped read succeeded queue depth=%u\n", qd);
        notice_printed = 1;
    }
    return 1;
}
#endif

/* Fill one compact slot for one expert weight (gate/up/down): zero-copy D2D from
 * the pinned host window when in-window, else stream straight from the file.
 * All async on the upload stream; caller batches one sync per layer. */
static int cuda_moe_fill_span(
        char *dst,
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        char *mirror) {
    if (cuda_model_range_in_window(model_map, offset, bytes)) {
        const char *src = g_model_device_base + offset;   /* device-mapped host window */
        if (mirror) {
            memcpy(mirror, (const char *)model_map + offset, (size_t)bytes);
            if (memcmp(mirror, (const char *)model_map + offset,
                       (size_t)bytes) != 0) {
                return 0;
            }
        }
        if (cudaMemcpyAsync(dst, src, (size_t)bytes, cudaMemcpyDefault, g_model_upload_stream) != cudaSuccess) {
            (void)cudaGetLastError();
            return 0;
        }
        return 1;
    }
    return cuda_model_stream_span_into(dst, offset, bytes, mirror);
}

static int cuda_moe_gather_ensure(char **ptr, uint64_t *cap, uint64_t bytes, const char *what) {
    if (bytes == 0) return 1;
    if (*ptr && *cap >= bytes) return 1;
    if (*ptr) { (void)cudaFree(*ptr); *ptr = NULL; *cap = 0; }
    char *dev = cuda_model_stream_alloc(bytes, 1, what);
    if (!dev) return 0;
    *ptr = dev; *cap = bytes; return 1;
}

static int cuda_moe_gather_ensure_i32(int32_t **ptr, uint64_t *cap, uint32_t count, const char *what) {
    return cuda_moe_gather_ensure((char **)ptr, cap, (uint64_t)count * sizeof(int32_t), what);
}

extern "C" int ds4_gpu_routed_moe_prepare_selected(
        const void *model_map, uint64_t model_size,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        const ds4_gpu_tensor *selected, uint32_t n_expert, uint32_t n_tokens) {
    g_moe_selected_prepared.valid = 0;
    const char *env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED");
    const char *full_env = getenv("DS4_CUDA_MOE_OVERLAP_SHARED_FULL");
    const int minimal_enabled = env && env[0] && strcmp(env, "0") != 0;
    const int full_enabled = full_env && full_env[0] && strcmp(full_env, "0") != 0;
    if ((!minimal_enabled && !full_enabled) ||
        getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") != NULL ||
        cuda_moe_expert_cache_requested() != 0) {
        return 0;
    }
    const uint32_t n_total_expert = 256u;
    if (!model_map || !selected || !selected->ptr || n_expert == 0 || n_tokens == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        n_tokens > UINT32_MAX / n_expert) {
        return 0;
    }
    const uint32_t slot_count = n_tokens * n_expert;
    if (selected->bytes < (uint64_t)slot_count * sizeof(int32_t) ||
        gate_expert_bytes > UINT64_MAX / n_total_expert ||
        down_expert_bytes > UINT64_MAX / n_total_expert) {
        return 0;
    }
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_offset > model_size || gate_bytes > model_size - gate_offset ||
        up_offset > model_size || gate_bytes > model_size - up_offset ||
        down_offset > model_size || down_bytes > model_size - down_offset) {
        return 0;
    }
    if (cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes)) {
        return 0;
    }

    g_moe_gather.h_sel.resize(slot_count);
    if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected->ptr,
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyDeviceToHost), "moe overlap selected D2H")) {
        return 0;
    }
    g_moe_selected_prepared.model_map = model_map;
    g_moe_selected_prepared.selected_ptr = selected->ptr;
    g_moe_selected_prepared.gate_offset = gate_offset;
    g_moe_selected_prepared.up_offset = up_offset;
    g_moe_selected_prepared.down_offset = down_offset;
    g_moe_selected_prepared.gate_expert_bytes = gate_expert_bytes;
    g_moe_selected_prepared.down_expert_bytes = down_expert_bytes;
    g_moe_selected_prepared.n_expert = n_expert;
    g_moe_selected_prepared.n_tokens = n_tokens;
    g_moe_selected_prepared.full = full_enabled;
    g_moe_selected_prepared.valid = 1;
    return 1;
}

/* Returns 1 and populates g_moe_gather (compact gate/up/down + remapped slot tensor)
 * on success; 0 on any failure (caller falls back to the whole-256-block path). */
static int cuda_moe_selected_load(
        const void *model_map, uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
        uint32_t n_total_expert, uint32_t n_expert, uint32_t n_tokens,
        const ds4_gpu_tensor *selected_arg,
        const ds4_gpu_tensor *weights_arg,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key) {
    g_moe_last_selected.valid = 0;
    (void)model_size;
    if (n_total_expert == 0 || n_expert == 0 || n_tokens == 0) return 0;
    if (!selected_arg || !selected_arg->ptr) return 0;
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (n_tokens > UINT32_MAX / n_expert) return 0;
    const uint32_t slot_count = n_tokens * n_expert;
    if (slot_count == 0) return 0;
    if (selected_arg->bytes < (uint64_t)slot_count * sizeof(int32_t)) return 0;
    const int layer_top1 =
        cuda_moe_expert_cache_requested() != 0 && cuda_moe_expert_cache_layer_top1();
    if (layer_top1 &&
        (!weights_arg || !weights_arg->ptr ||
         weights_arg->bytes < (uint64_t)slot_count * sizeof(float))) {
        return 0;
    }

    const int prepared =
        g_moe_selected_prepared.valid &&
        g_moe_selected_prepared.model_map == model_map &&
        g_moe_selected_prepared.selected_ptr == selected_arg->ptr &&
        g_moe_selected_prepared.gate_offset == gate_offset &&
        g_moe_selected_prepared.up_offset == up_offset &&
        g_moe_selected_prepared.down_offset == down_offset &&
        g_moe_selected_prepared.gate_expert_bytes == gate_expert_bytes &&
        g_moe_selected_prepared.down_expert_bytes == down_expert_bytes &&
        g_moe_selected_prepared.n_expert == n_expert &&
        g_moe_selected_prepared.n_tokens == n_tokens;
    g_moe_selected_prepared.valid = 0;
    if (prepared && g_moe_selected_prepared.full) {
        static int full_overlap_notice_printed = 0;
        if (!full_overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE full shared-overlap consumed\n");
            full_overlap_notice_printed = 1;
        }
    } else if (prepared) {
        static int overlap_notice_printed = 0;
        if (!overlap_notice_printed) {
            fprintf(stderr, "ds4: CUDA MoE shared-overlap consumed\n");
            overlap_notice_printed = 1;
        }
    }

    /* 1. Router outputs -> host. Layer-top1 also consumes the selected weights
     * to choose residency; selection itself remains unchanged. */
    if (prepared) {
        if (g_moe_gather.h_sel.size() != slot_count) return 0;
    } else if (layer_top1) {
        g_moe_gather.h_sel.resize(slot_count);
        g_moe_gather.h_weights.resize(slot_count);
        if (!cuda_ok(cudaMemcpyAsync(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                     (size_t)slot_count * sizeof(int32_t),
                                     cudaMemcpyDeviceToHost, 0), "moe selected D2H enqueue") ||
            !cuda_ok(cudaMemcpyAsync(g_moe_gather.h_weights.data(), weights_arg->ptr,
                                     (size_t)slot_count * sizeof(float),
                                     cudaMemcpyDeviceToHost, 0), "moe weights D2H enqueue") ||
            !cuda_ok(cudaStreamSynchronize(0), "moe router D2H sync")) return 0;
    } else {
        g_moe_gather.h_sel.resize(slot_count);
        if (!cuda_ok(cudaMemcpy(g_moe_gather.h_sel.data(), selected_arg->ptr,
                                (size_t)slot_count * sizeof(int32_t),
                                cudaMemcpyDeviceToHost), "moe selected D2H")) return 0;
    }

    /* Residency learning consumes the exact selected ids already required by
     * execution. It does not change router scores, top-k, or the active mask. */
    cuda_dynamic_arena_observe_selected(
        layer_index, n_tokens, g_moe_gather.h_sel.data(), slot_count);

    /* 2. dedupe -> compact ids (ascending expert order) + per-slot remap */
    std::vector<int32_t> &e2s = g_moe_gather.h_expert_to_slot;
    e2s.assign(n_total_expert, -1);
    std::vector<int32_t> &compact = g_moe_gather.h_compact_ids; compact.clear();
    std::vector<int32_t> &slots = g_moe_gather.h_slot_ids; slots.resize(slot_count);
    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t e = g_moe_gather.h_sel[i];
        if (e < 0 || (uint32_t)e >= n_total_expert) return 0;
        e2s[(uint32_t)e] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (e2s[e] != -2) continue;
        e2s[e] = (int32_t)compact.size();
        compact.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++)
        slots[i] = e2s[(uint32_t)g_moe_gather.h_sel[i]];
    const uint32_t compact_count = (uint32_t)compact.size();
    if (compact_count == 0 || compact_count > n_total_expert) return 0;

    /* 3. compact device buffers (grow-only, reused across layers/tokens) */
    const uint64_t cgate = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t cdown = (uint64_t)compact_count * down_expert_bytes;
    if (!cuda_moe_gather_ensure(&g_moe_gather.gate, &g_moe_gather.gate_cap, cgate, "moe gather gate") ||
        !cuda_moe_gather_ensure(&g_moe_gather.up,   &g_moe_gather.up_cap,   cgate, "moe gather up") ||
        !cuda_moe_gather_ensure(&g_moe_gather.down, &g_moe_gather.down_cap, cdown, "moe gather down") ||
        !cuda_moe_gather_ensure_i32(&g_moe_gather.slot, &g_moe_gather.slot_cap, slot_count, "moe gather slots"))
        return 0;

    /* Dynamic-arena hits go straight from their stable pinned slot to the
     * compact execution buffers. They never enter the legacy pread/staging
     * list and never take a detour through the persistent VRAM cache. */
    std::vector<uint8_t> &arena_resident = g_moe_gather.h_arena_resident;
    arena_resident.assign(compact_count, 0);
    const int arena_active = g_dynamic_arena.host_base &&
        g_dynamic_arena.snapshot_generation != 0 &&
        !g_dynamic_arena.hits_disabled &&
        !g_dynamic_arena.submissions_blocked;
    if (arena_active) {
        for (uint32_t i = 0; i < compact_count; i++) {
            const uint32_t expert = (uint32_t)compact[i];
            const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
            const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
            const cuda_dynamic_arena_copy_status arena_status =
                cuda_dynamic_arena_copy_expert_async(
                    model_map, layer_index, expert,
                    gate_offset, up_offset, down_offset,
                    g_moe_gather.gate + gate_dst,
                    g_moe_gather.up + gate_dst,
                    g_moe_gather.down + down_dst,
                    gate_expert_bytes, gate_expert_bytes,
                    down_expert_bytes);
            if (arena_status == CUDA_DYNAMIC_ARENA_FATAL) {
                (void)cudaStreamSynchronize(g_model_upload_stream);
                return 0;
            }
            arena_resident[i] =
                arena_status == CUDA_DYNAMIC_ARENA_ENQUEUED ? 1u : 0u;
        }
    }

    int spex_prefetch_slot = -1;
    uint32_t spex_prediction_slot = 0;
    uint32_t spex_compact_slot = UINT32_MAX;
    if (spex_queue && spex_key && cuda_moe_expert_cache_requested() == 0) {
        (void)cuda_spex_prefetch_claim(
            spex_queue, spex_key,
            gate_offset, up_offset, down_offset,
            compact,
            &spex_prefetch_slot,
            &spex_prediction_slot,
            &spex_compact_slot);
        if (spex_prefetch_slot >= 0 &&
            spex_compact_slot < arena_resident.size() &&
            arena_resident[spex_compact_slot]) {
            cuda_spex_prefetch_release(
                spex_queue, spex_prefetch_slot, 1, 0);
            spex_prefetch_slot = -1;
            spex_compact_slot = UINT32_MAX;
        }
    }

    /* 4. Resolve exact-byte resident hits, admit misses into persistent VRAM
     * slots when enabled, and stream overflow misses directly into compact
     * buffers. Cache policy changes residency only; router selection and the
     * compact slot map are unchanged. */
    const int prof = getenv("DS4_CUDA_SEL_PROFILE") != NULL;
    const double t_fetch0 = prof ? cuda_wall_sec() : 0.0;
    cuda_moe_expert_cache *cache =
        cuda_moe_expert_cache_prepare(gate_expert_bytes, down_expert_bytes);
    std::vector<cuda_moe_gather::span> &spans = g_moe_gather.h_spans;
    std::vector<int32_t> &cache_slots = g_moe_gather.h_cache_slots;
    std::vector<uint8_t> &claimed = g_moe_gather.h_cache_claimed;
    std::vector<uint32_t> &admission_compact = g_moe_gather.h_cache_admission_compact;
    std::vector<uint32_t> &admission_slots = g_moe_gather.h_cache_admission_slots;
    std::vector<uint8_t> &admission_evicted = g_moe_gather.h_cache_admission_evicted;
    spans.clear();
    spans.reserve((size_t)compact_count * 3u);
    cache_slots.assign(compact_count, -1);
    claimed.assign(cache ? cache->capacity : 0u, 0u);
    admission_compact.clear();
    admission_slots.clear();
    admission_evicted.clear();
    admission_compact.reserve(compact_count);
    admission_slots.reserve(compact_count);
    admission_evicted.reserve(compact_count);

    uint64_t local_hits = 0;
    uint64_t local_misses = 0;
    uint64_t local_evictions = 0;
    uint64_t local_direct = 0;

    auto expert_key = [&](uint32_t compact_slot) {
        const uint64_t e = (uint64_t)(uint32_t)compact[compact_slot];
        return cuda_moe_cache_key{
            gate_offset + e * gate_expert_bytes,
            up_offset + e * gate_expert_bytes,
            down_offset + e * down_expert_bytes,
        };
    };
    auto append_span = [&](char *destination,
                           uint64_t source,
                           uint64_t bytes,
                           uint32_t expert,
                           uint8_t part) {
        uint32_t arena_entry = UINT32_MAX;
        char *mirror = cuda_dynamic_arena_observer_mirror_ptr(
            model_map, layer_index, expert, part, source, bytes,
            &arena_entry);
        spans.push_back({
            destination, source, bytes, mirror, arena_entry, part
        });
    };
    auto append_direct = [&](uint32_t compact_slot, const cuda_moe_cache_key &key) {
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(
            g_moe_gather.gate + (uint64_t)compact_slot * gate_expert_bytes,
            key.gate_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(
            g_moe_gather.up + (uint64_t)compact_slot * gate_expert_bytes,
            key.up_src, gate_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(
            g_moe_gather.down + (uint64_t)compact_slot * down_expert_bytes,
            key.down_src, down_expert_bytes, expert,
            CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
        local_direct++;
    };
    auto append_admission = [&](uint32_t compact_slot, uint32_t cache_slot,
                                 const cuda_moe_cache_key &key) {
        cuda_moe_cache_slot &entry = cache->slots[cache_slot];
        const uint8_t evicted = entry.state == CUDA_MOE_CACHE_VALID ? 1u : 0u;
        entry.state = CUDA_MOE_CACHE_LOADING;
        entry.key = key;
        entry.age = 0;
        claimed[cache_slot] = 1;
        cache_slots[compact_slot] = (int32_t)cache_slot;
        admission_compact.push_back(compact_slot);
        admission_slots.push_back(cache_slot);
        admission_evicted.push_back(evicted);
        local_evictions += evicted;
        const uint64_t gate_dst = (uint64_t)cache_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)cache_slot * down_expert_bytes;
        const uint32_t expert = (uint32_t)compact[compact_slot];
        append_span(cache->gate + gate_dst, key.gate_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_GATE);
        append_span(cache->up + gate_dst, key.up_src,
                    gate_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_UP);
        append_span(cache->down + down_dst, key.down_src,
                    down_expert_bytes, expert,
                    CUDA_DYNAMIC_ARENA_MIRROR_DOWN);
    };
    auto discard_admissions = [&]() {
        if (!cache) return;
        for (size_t i = 0; i < admission_slots.size(); i++) {
            cuda_moe_cache_slot &entry = cache->slots[admission_slots[i]];
            if (admission_evicted[i] && cache->count > 0) cache->count--;
            entry.state = CUDA_MOE_CACHE_EMPTY;
        }
    };

    if (cache && layer_top1) {
        int layer_slot = -1;
        for (uint32_t i = 0; i < cache->capacity; i++) {
            if (cache->slots[i].layer_owned && cache->slots[i].layer_key == gate_offset) {
                layer_slot = (int)i;
                break;
            }
        }
        if (layer_slot < 0) {
            for (uint32_t i = 0; i < cache->capacity; i++) {
                if (cache->slots[i].layer_owned) continue;
                cache->slots[i].layer_owned = 1;
                cache->slots[i].layer_key = gate_offset;
                layer_slot = (int)i;
                break;
            }
        }

        if (layer_slot >= 0 && cache->slots[(uint32_t)layer_slot].state == CUDA_MOE_CACHE_VALID) {
            const cuda_moe_cache_key resident = cache->slots[(uint32_t)layer_slot].key;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                if (key.gate_src == resident.gate_src &&
                    key.up_src == resident.up_src &&
                    key.down_src == resident.down_src) {
                    cache_slots[i] = layer_slot;
                    claimed[(uint32_t)layer_slot] = 1;
                    local_hits = 1;
                    break;
                }
            }
        }
        uint32_t cache_eligible = 0;
        for (uint32_t i = 0; i < compact_count; i++) {
            cache_eligible += arena_resident[i] == 0;
        }
        local_misses = cache_eligible - local_hits;

        if (layer_slot >= 0 && local_hits == 0) {
            std::vector<float> &mass = g_moe_gather.h_compact_mass;
            mass.assign(compact_count, 0.0f);
            for (uint32_t i = 0; i < slot_count; i++) {
                mass[(uint32_t)slots[i]] += g_moe_gather.h_weights[i];
            }
            uint32_t candidate = UINT32_MAX;
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i]) continue;
                if (candidate == UINT32_MAX || mass[i] > mass[candidate]) {
                    candidate = i;
                }
            }
            if (candidate != UINT32_MAX) {
                append_admission(candidate, (uint32_t)layer_slot,
                                 expert_key(candidate));
            }
        }
        for (uint32_t i = 0; i < compact_count; i++) {
            if (!arena_resident[i] && cache_slots[i] < 0 &&
                i != spex_compact_slot) {
                append_direct(i, expert_key(i));
            }
        }
    } else {
        if (cache) {
            for (uint32_t i = 0; i < compact_count; i++) {
                if (arena_resident[i]) continue;
                const cuda_moe_cache_key key = expert_key(i);
                const int slot = cuda_moe_expert_cache_find(cache, key);
                if (slot >= 0 && !claimed[(uint32_t)slot]) {
                    cache_slots[i] = slot;
                    claimed[(uint32_t)slot] = 1;
                    local_hits++;
                } else {
                    local_misses++;
                }
            }
        }

        for (uint32_t i = 0; i < compact_count; i++) {
            if (arena_resident[i]) continue;
            if (cache_slots[i] >= 0) continue;
            if (i == spex_compact_slot) continue;
            const cuda_moe_cache_key key = expert_key(i);
            const int cache_slot = cache ? cuda_moe_expert_cache_lru_slot(cache, claimed) : -1;
            if (cache_slot >= 0) {
                append_admission(i, (uint32_t)cache_slot, key);
            } else {
                append_direct(i, key);
            }
        }
    }
    int fill_ok = 0;
    if (spex_prefetch_slot >= 0) {
        const uint64_t gate_dst = (uint64_t)spex_compact_slot * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)spex_compact_slot * down_expert_bytes;
        if (!cuda_spex_prefetch_copy_to_compact(
                spex_queue,
                (uint32_t)spex_prefetch_slot,
                spex_prediction_slot,
                g_moe_gather.gate + gate_dst,
                g_moe_gather.up + gate_dst,
                g_moe_gather.down + down_dst)) {
            (void)cudaGetLastError();
            const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
            cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
            return 0;
        }
    }
#ifdef _WIN32
    const uint32_t io_qd = cuda_moe_io_queue_depth();
    if (io_qd > 1u) {
        fill_ok = cuda_moe_fill_spans_overlapped(model_map, spans, io_qd);
        if (!fill_ok) {
            fprintf(stderr, "ds4: CUDA MoE overlapped read failed; selected-load fallback requested\n");
        }
    }
    else
#endif
    {
        fill_ok = 1;
        for (const cuda_moe_gather::span &s : spans) {
            if (!cuda_moe_fill_span(
                    s.dst, model_map, s.offset, s.bytes, s.mirror)) {
                fill_ok = 0;
                break;
            }
            if (s.mirror) {
                cuda_dynamic_arena_observer_mirror_done(
                    s.arena_entry, s.arena_part, s.bytes);
            }
        }
    }
    if (!fill_ok) {
        const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
        discard_admissions();
        return 0;
    }

    if (cache) {
        for (uint32_t i = 0; i < compact_count; i++) {
            if (cache_slots[i] < 0) continue;
            if (!cuda_moe_expert_cache_copy_to_compact_async(
                    cache, (uint32_t)cache_slots[i], i)) {
                (void)cudaGetLastError();
                const int fenced = cudaStreamSynchronize(g_model_upload_stream) == cudaSuccess;
                cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, fenced, 0);
                discard_admissions();
                return 0;
            }
        }
    }

    if (!cuda_ok(cudaStreamSynchronize(g_model_upload_stream), "moe compact upload sync")) {
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 0, 0);
        if (cache) cuda_moe_expert_cache_invalidate();
        return 0;
    }
    if (cache) {
        for (size_t i = 0; i < admission_slots.size(); i++) {
            cuda_moe_cache_slot &entry = cache->slots[admission_slots[i]];
            entry.state = CUDA_MOE_CACHE_VALID;
            if (!admission_evicted[i] && cache->count < cache->capacity) cache->count++;
        }
        for (int32_t slot : cache_slots) {
            if (slot >= 0) cache->slots[(uint32_t)slot].age = ++cache->tick;
        }
        cache->calls++;
        cache->hits += local_hits;
        cache->misses += local_misses;
        cache->admissions += admission_slots.size();
        cache->evictions += local_evictions;
        cache->direct_loads += local_direct;
        const uint64_t stats_interval = cuda_moe_expert_cache_stats_interval();
        if (stats_interval != 0 && cache->calls % stats_interval == 0u) {
            const uint64_t lookups = cache->hits + cache->misses;
            fprintf(stderr,
                    "ds4: [moecache] calls=%llu cap=%u count=%u hits=%llu misses=%llu hit_rate=%.3f admissions=%llu evictions=%llu direct=%llu\n",
                    (unsigned long long)cache->calls, cache->capacity, cache->count,
                    (unsigned long long)cache->hits, (unsigned long long)cache->misses,
                    lookups ? (double)cache->hits / (double)lookups : 0.0,
                    (unsigned long long)cache->admissions,
                    (unsigned long long)cache->evictions,
                    (unsigned long long)cache->direct_loads);
        }
    }
    if (prof) {
        g_sel_prof_calls++;
        g_sel_prof_experts += compact_count;
        g_sel_prof_fetch_s += cuda_wall_sec() - t_fetch0;
        if (g_sel_prof_calls % 60u == 0u) {
            fprintf(stderr, "ds4: [selprof] calls=%llu experts=%llu fill=%.3fs (%.2f ms/expert)\n",
                    (unsigned long long)g_sel_prof_calls, (unsigned long long)g_sel_prof_experts,
                    g_sel_prof_fetch_s,
                    g_sel_prof_experts ? 1000.0 * g_sel_prof_fetch_s / (double)g_sel_prof_experts : 0.0);
        }
    }

    /* 5. publish the remapped selection (compact-slot indices) */
    if (!cuda_ok(cudaMemcpy(g_moe_gather.slot, slots.data(),
                            (size_t)slot_count * sizeof(int32_t),
                            cudaMemcpyHostToDevice), "moe gather slots")) {
        cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 0);
        return 0;
    }
    g_moe_gather.slot_tensor.ptr = g_moe_gather.slot;
    g_moe_gather.slot_tensor.bytes = (uint64_t)slot_count * sizeof(int32_t);
    g_moe_gather.slot_tensor.owner = 0;

    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA MoE selected-load slots=%u compact=%u gate/up %.2f MiB down %.2f MiB\n",
                slot_count, compact_count,
                (double)cgate / 1048576.0, (double)cdown / 1048576.0);
    }
    g_moe_last_selected.gate_offset = gate_offset;
    g_moe_last_selected.count = compact_count;
    memcpy(g_moe_last_selected.ids, compact.data(),
           (size_t)compact_count * sizeof(g_moe_last_selected.ids[0]));
    g_moe_last_selected.valid = 1;
    cuda_spex_prefetch_release(spex_queue, spex_prefetch_slot, 1, 1);
    return 1;
}

extern "C" uint32_t ds4_gpu_routed_moe_last_selected(
        uint64_t gate_offset,
        int32_t *out_ids,
        uint32_t out_cap) {
    if (!out_ids || out_cap == 0 || !g_moe_last_selected.valid ||
        g_moe_last_selected.gate_offset != gate_offset) {
        return 0;
    }
    uint32_t count = g_moe_last_selected.count;
    if (count > out_cap) count = out_cap;
    memcpy(out_ids, g_moe_last_selected.ids,
           (size_t)count * sizeof(g_moe_last_selected.ids[0]));
    return count;
}

static int routed_moe_launch(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer_index,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t n_tokens,
        ds4_gpu_spex_queue *spex_queue,
        const ds4_gpu_spex_key *spex_key) {
    g_moe_last_selected.valid = 0;
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    if (gate_type != 16u || down_type != 10u) return 0;
    const uint32_t n_total_expert = 256u;
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_bytes > model_size - gate_offset ||
        gate_bytes > model_size - up_offset ||
        down_bytes > model_size - down_offset) {
        return 0;
    }
    const char *gate_w = NULL;
    const char *up_w = NULL;
    const char *down_w = NULL;
    /* Selected-expert load: when the whole 256-expert block is beyond the pinned
     * host window (streaming regime), fetch/gather ONLY the routed experts into a
     * compact VRAM buffer and rebind `selected` to compact slots -- the unchanged
     * MoE kernels then touch top-6 of 256 (~42x less streamed per layer). Falls
     * back to the whole-block path on failure or when fully in-window (zero-copy). */
    const int whole_in_window =
        cuda_model_range_in_window(model_map, gate_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, up_offset, gate_bytes) &&
        cuda_model_range_in_window(model_map, down_offset, down_bytes);
    if (!whole_in_window && getenv("DS4_CUDA_MOE_NO_SELECTED_LOAD") == NULL &&
        cuda_moe_selected_load(model_map, model_size, layer_index,
                               gate_offset, up_offset, down_offset,
                               gate_expert_bytes, down_expert_bytes,
                               n_total_expert, n_expert, n_tokens, selected, weights,
                               spex_queue, spex_key)) {
        gate_w = g_moe_gather.gate;
        up_w = g_moe_gather.up;
        down_w = g_moe_gather.down;
        selected = &g_moe_gather.slot_tensor;   /* kernels index compact slots */
    } else {
        ds4_gpu_spex_queue_cancel(spex_queue, spex_key);
        gate_w = cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
        up_w = cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
        down_w = cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
    }
    if (!gate_w || !up_w || !down_w) return 0;

    int ok = 1;
    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
    const uint64_t xq_count = (uint64_t)n_tokens * xq_blocks;
    const uint64_t midq_count = (uint64_t)n_tokens * n_expert * midq_blocks;
    const uint64_t xq_bytes = xq_count * sizeof(cuda_block_q8_K);
    const uint64_t midq_bytes = midq_count * sizeof(cuda_block_q8_K);
    if (down->bytes >= xq_bytes && gate->bytes >= midq_bytes) {
        cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
        cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
        const uint32_t profile_moe = getenv("DS4_CUDA_MOE_PROFILE") != NULL;
        cudaEvent_t prof_ev[7] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL};
        if (profile_moe) {
            for (uint32_t i = 0; i < 7u; i++) {
                if (cudaEventCreate(&prof_ev[i]) != cudaSuccess) {
                    for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(prof_ev[j]);
                    memset(prof_ev, 0, sizeof(prof_ev));
                    break;
                }
            }
            if (prof_ev[0]) (void)cudaEventRecord(prof_ev[0], 0);
        }
        const uint32_t pair_count = n_tokens * n_expert;
        const uint32_t use_sorted_pairs = n_tokens > 1u;
        const uint32_t use_expert_tiles = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL;
        const uint32_t expert_tile_m = getenv("DS4_CUDA_MOE_TILE4") ? 4u : 8u;
        const uint32_t write_gate_up = getenv("DS4_CUDA_MOE_WRITE_GATE_UP") != NULL;
        const uint32_t use_p2_sorted = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_P2") == NULL;
        const uint32_t use_atomic_down = use_expert_tiles &&
            (getenv("DS4_CUDA_MOE_ATOMIC_DOWN") != NULL ||
             (n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_ATOMIC_DOWN") == NULL));
        const uint32_t use_gate_row2048 = use_expert_tiles && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW128") != NULL ||
             (n_tokens >= 128u &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW128") == NULL));
        const uint32_t use_down_tile16 = use_atomic_down && expert_tile_m == 8u &&
            n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_DOWN_TILE16") == NULL;
        const uint32_t use_down_block16 = use_down_tile16 && midq_blocks <= 8u &&
            getenv("DS4_CUDA_MOE_NO_DOWN_BLOCK16") == NULL;
        const uint32_t use_decode_lut_gate =
            n_tokens == 1u && xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL;
        const uint32_t gate_row_span =
            getenv("DS4_CUDA_MOE_GATE_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ? 2048u : 1024u;
        const uint32_t down_row_span =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ? 1024u : 2048u;
        const uint32_t use_down_row2048 = use_atomic_down && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW128") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW64") != NULL ||
             (use_down_tile16 &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW128") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW64") == NULL));
        const uint32_t use_direct_down_sum6 =
            n_tokens == 1u && n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        uint32_t *sorted_pairs = NULL;
        uint32_t *sorted_offsets = NULL;
        uint32_t *sorted_counts = NULL;
        uint32_t *tile_total = NULL;
        uint32_t *tile_experts = NULL;
        uint32_t *tile_starts = NULL;
        uint32_t *tile16_total = NULL;
        uint32_t *tile16_experts = NULL;
        uint32_t *tile16_starts = NULL;
        uint32_t tile_capacity = 0;
        uint32_t tile16_capacity = 0;
        dim3 xq_grid(xq_blocks, n_tokens, 1);
        q8_K_quantize_kernel<<<xq_grid, 256>>>(xq, (const float *)x->ptr, expert_in_dim, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe x quantize launch");
        if (prof_ev[1]) (void)cudaEventRecord(prof_ev[1], 0);
        if (ok && use_sorted_pairs) {
            const uint64_t counts_bytes = 256ull * sizeof(uint32_t);
            const uint64_t offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t cursors_bytes = 256ull * sizeof(uint32_t);
            const uint64_t sorted_bytes = (uint64_t)pair_count * sizeof(uint32_t);
            tile_capacity = (pair_count + expert_tile_m - 1u) / expert_tile_m + 256u;
            tile16_capacity = use_down_tile16 ? ((pair_count + 15u) / 16u + 256u) : 0u;
            const uint64_t tile_offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t tile_total_bytes = sizeof(uint32_t);
            const uint64_t tile_experts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile_starts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile16_offsets_bytes = use_down_tile16 ? 257ull * sizeof(uint32_t) : 0u;
            const uint64_t tile16_total_bytes = use_down_tile16 ? sizeof(uint32_t) : 0u;
            const uint64_t tile16_experts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile16_starts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile_offsets_off = counts_bytes + offsets_bytes + cursors_bytes + sorted_bytes;
            const uint64_t tile_total_off = tile_offsets_off + tile_offsets_bytes;
            const uint64_t tile_experts_off = tile_total_off + tile_total_bytes;
            const uint64_t tile_starts_off = tile_experts_off + tile_experts_bytes;
            const uint64_t tile16_offsets_off = tile_starts_off + tile_starts_bytes;
            const uint64_t tile16_total_off = tile16_offsets_off + tile16_offsets_bytes;
            const uint64_t tile16_experts_off = tile16_total_off + tile16_total_bytes;
            const uint64_t tile16_starts_off = tile16_experts_off + tile16_experts_bytes;
            const uint64_t scratch_bytes = tile16_starts_off + tile16_starts_bytes;
            uint8_t *scratch = (uint8_t *)cuda_tmp_alloc(scratch_bytes,
                                                         "routed_moe sorted pairs");
            if (!scratch) {
                ok = 0;
            } else {
                uint32_t *counts = (uint32_t *)scratch;
                uint32_t *offsets = (uint32_t *)(scratch + counts_bytes);
                uint32_t *cursors = (uint32_t *)(scratch + counts_bytes + offsets_bytes);
                sorted_pairs = (uint32_t *)(scratch + counts_bytes + offsets_bytes + cursors_bytes);
                sorted_offsets = offsets;
                sorted_counts = counts;
                uint32_t *tile_offsets = (uint32_t *)(scratch + tile_offsets_off);
                tile_total = (uint32_t *)(scratch + tile_total_off);
                tile_experts = (uint32_t *)(scratch + tile_experts_off);
                tile_starts = (uint32_t *)(scratch + tile_starts_off);
                uint32_t *tile16_offsets = use_down_tile16 ? (uint32_t *)(scratch + tile16_offsets_off) : NULL;
                tile16_total = use_down_tile16 ? (uint32_t *)(scratch + tile16_total_off) : NULL;
                tile16_experts = use_down_tile16 ? (uint32_t *)(scratch + tile16_experts_off) : NULL;
                tile16_starts = use_down_tile16 ? (uint32_t *)(scratch + tile16_starts_off) : NULL;
                ok = cuda_ok(cudaMemset(counts, 0, counts_bytes), "routed_moe sorted counts clear");
                if (ok) {
                    moe_count_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        counts,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted count launch");
                }
                if (ok) {
                    moe_prefix_sorted_pairs_kernel<<<1, 1>>>(offsets, cursors, counts);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted prefix launch");
                }
                if (ok) {
                    moe_scatter_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256>>>(
                        sorted_pairs,
                        cursors,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted scatter launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile_offsets, tile_total, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile offsets launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile_experts, tile_starts, tile_offsets, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tiles launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1>>>(tile16_offsets, tile16_total, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 offsets launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tiles_kernel<<<1, 256>>>(tile16_experts, tile16_starts, tile16_offsets, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 launch");
                }
            }
        }
        if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
        if (ok) {
            dim3 mgrid((expert_mid_dim + 31u) / 32u, n_tokens * n_expert, 1);
            if (ok && sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts && tile_total && tile_experts && tile_starts) {
                if (use_gate_row2048) {
                    if (gate_row_span == 512u) {
                        dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<512><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else if (gate_row_span == 1024u) {
                        dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<1024><<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else {
                        dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_row2048_kernel<<<tgrid, 256>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                } else {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                }
            } else if (ok && sorted_pairs && use_p2_sorted) {
                dim3 p2_mgrid((expert_mid_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_gate_up_mid_sorted_p2_qwarp32_kernel<<<p2_mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
            } else if (ok && sorted_pairs) {
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
            } else if (ok) {
                dim3 qgrid((expert_mid_dim + 127u) / 128u, n_tokens * n_expert, 1);
                if (use_decode_lut_gate) {
                    moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else {
                    moe_gate_up_mid_qwarp32_kernel<<<qgrid, 256>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
                }
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
        }
        if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
        if (ok) {
            dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
            q8_K_quantize_kernel<<<midq_grid, 256>>>(midq, (const float *)mid->ptr, expert_mid_dim, n_tokens * n_expert);
            ok = cuda_ok(cudaGetLastError(), "routed_moe mid quantize launch");
        }
        if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
        if (ok) {
            dim3 dgrid((out_dim + 31u) / 32u, n_tokens * n_expert, 1);
            uint32_t *down_tile_total = tile_total;
            uint32_t *down_tile_experts = tile_experts;
            uint32_t *down_tile_starts = tile_starts;
            uint32_t down_tile_capacity = tile_capacity;
            if (use_down_tile16 && tile16_total && tile16_experts && tile16_starts) {
                down_tile_total = tile16_total;
                down_tile_experts = tile16_experts;
                down_tile_starts = tile16_starts;
                down_tile_capacity = tile16_capacity;
            }
            if (use_direct_down_sum6) {
                dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                moe_down_sum6_qwarp32_kernel<<<sgrid, 256>>>(
                    (float *)out->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim);
            } else if (use_atomic_down) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                zero_kernel<<<(n + 255u) / 256u, 256>>>((float *)out->ptr, n);
                ok = cuda_ok(cudaGetLastError(), "routed_moe atomic zero launch");
            }
            if (use_direct_down_sum6) {
                /* The direct decode kernel writes the final token row. */
            } else if (sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts &&
                down_tile_total && down_tile_experts && down_tile_starts) {
                if (use_down_row2048) {
                    if (down_row_span == 512u) {
                        dim3 tgrid((out_dim + 511u) / 512u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<512><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else if (down_row_span == 1024u) {
                        dim3 tgrid((out_dim + 1023u) / 1024u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_rowspan_kernel<1024><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    } else {
                        dim3 tgrid((out_dim + 2047u) / 2048u, down_tile_capacity, 1);
                        if (use_down_block16) {
                            moe_down_expert_tile16_rowspan_block16_kernel<2048><<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        } else {
                            moe_down_expert_tile16_row2048_kernel<<<tgrid, 256>>>(
                                use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                                down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                                down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                                midq_blocks, out_dim, n_expert, use_atomic_down);
                        }
                    }
                } else if (use_down_tile16) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile16_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile8_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile4_row32_kernel<<<tgrid, 256>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                }
            } else if (sorted_pairs && use_p2_sorted) {
                dim3 p2_dgrid((out_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_down_sorted_p2_qwarp32_kernel<<<p2_dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
            } else if (sorted_pairs) {
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else {
                moe_down_qwarp32_kernel<<<dgrid, 256>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
        }
        if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
        if (ok && !use_atomic_down && !use_direct_down_sum6) {
            uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
            ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
        }
        if (prof_ev[6]) {
            (void)cudaEventRecord(prof_ev[6], 0);
            if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                float ms_xq = 0.0f, ms_sort = 0.0f, ms_gate = 0.0f, ms_midq = 0.0f, ms_down = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                (void)cudaEventElapsedTime(&ms_sort, prof_ev[1], prof_ev[2]);
                (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                fprintf(stderr,
                        "ds4: CUDA MoE profile tokens=%u pairs=%u xq=%.3f sort=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                        n_tokens, pair_count, ms_xq, ms_sort, ms_gate, ms_midq, ms_down, ms_sum, ms_total);
            }
            for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
        }
        return ok;
    }

    if (ok) {
        dim3 mgrid(expert_mid_dim, n_tokens * n_expert, 1);
        moe_gate_up_mid_f32_kernel<<<mgrid, 256>>>(
            (float *)gate->ptr,
            (float *)up->ptr,
            (float *)mid->ptr,
            gate_w,
            up_w,
            (const float *)x->ptr,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            gate_expert_bytes,
            gate_row_bytes,
            expert_in_dim,
            expert_mid_dim,
            n_expert,
            clamp);
        ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
    }
    if (ok) {
        dim3 dgrid(out_dim, n_tokens * n_expert, 1);
        moe_down_f32_kernel<<<dgrid, 256>>>(
            (float *)down->ptr,
            down_w,
            (const float *)mid->ptr,
            (const int32_t *)selected->ptr,
            down_expert_bytes,
            down_row_bytes,
            expert_mid_dim,
            out_dim,
            n_expert);
        ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
    }
    if (ok) {
        uint64_t n = (uint64_t)n_tokens * out_dim;
        moe_sum_kernel<<<(n + 255) / 256, 256>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
    }
    return ok;
}

extern "C" int ds4_gpu_routed_moe_one_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, ds4_gpu_spex_queue *spex_queue, const ds4_gpu_spex_key *spex_key) {
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             layer_index,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_expert, clamp, x, 1,
                             spex_queue, spex_key);
}
extern "C" int ds4_gpu_routed_moe_batch_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint32_t layer_index, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, uint32_t n_tokens, bool *mid_is_f16) {
    if (mid_is_f16) *mid_is_f16 = false;
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             layer_index,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_expert, clamp, x, n_tokens,
                             NULL, NULL);
}
extern "C" int ds4_gpu_hc_split_sinkhorn_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *mix, const void *model_map, uint64_t model_size, uint64_t scale_offset, uint64_t base_offset, uint32_t n_hc, uint32_t sinkhorn_iters, float eps) {
    if (!out || !mix || !model_map || n_hc != 4) return 0;
    const uint64_t mix_bytes = 24ull * sizeof(float);
    if (scale_offset > model_size || model_size - scale_offset < 3ull * sizeof(float) ||
        base_offset > model_size || model_size - base_offset < mix_bytes ||
        mix->bytes < mix_bytes || out->bytes < mix_bytes) return 0;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    uint32_t n_rows = (uint32_t)(mix->bytes / mix_bytes);
    if (out->bytes / mix_bytes < n_rows) n_rows = (uint32_t)(out->bytes / mix_bytes);
    hc_split_sinkhorn_kernel<<<(n_rows + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)mix->ptr,
        scale,
        base,
        n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc_split_sinkhorn launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *weights, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)weights->ptr,
        n_embd, n_hc, n_tokens, n_hc);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_split_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    uint32_t stride = (uint32_t)(2u * n_hc + n_hc * n_hc);
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)split->ptr,
        n_embd, n_hc, n_tokens, stride);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum_split launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc != 4) {
        return 0;
    }
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
        scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || mix_bytes > model_size - base_offset) {
        return 0;
    }
    uint64_t n_rows = out->bytes / out_row_bytes;
    if (mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    hc_split_weighted_sum_fused_kernel<<<(uint32_t)n_rows, 256>>>(
            (float *)out->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc split weighted sum launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (getenv("DS4_CUDA_DISABLE_HC_SPLIT_NORM_FUSED") == NULL) {
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
            n_embd == 0 || n_hc != 4) {
            return 0;
        }
        const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
            norm_out->bytes < out->bytes ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) {
            return 0;
        }
        uint64_t n_rows = out->bytes / out_row_bytes;
        if (n_rows == 1) {
            if (mix->bytes < n_rows * mix_bytes ||
                split->bytes < n_rows * mix_bytes ||
                residual_hc->bytes < n_rows * residual_row_bytes) {
                return 0;
            }
            const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                    3ull * sizeof(float), "hc_scale");
            const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                    mix_bytes, "hc_base");
            const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                    (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
            if (!scale || !base || !norm_w) return 0;
            hc_split_weighted_sum_norm_fused_kernel<<<(uint32_t)n_rows, 256>>>(
                    (float *)out->ptr,
                    (float *)norm_out->ptr,
                    (float *)split->ptr,
                    (const float *)mix->ptr,
                    (const float *)residual_hc->ptr,
                    scale,
                    base,
                    norm_w,
                    n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps, norm_eps);
            return cuda_ok(cudaGetLastError(), "hc split weighted sum norm launch");
        }
    }
    return ds4_gpu_hc_split_weighted_sum_tensor(out, split, mix, residual_hc,
                                                  model_map, model_size,
                                                  scale_offset, base_offset,
                                                  n_embd, n_hc,
                                                  sinkhorn_iters, eps) &&
           ds4_gpu_rms_norm_weight_tensor(norm_out, out, model_map, model_size,
                                            norm_weight_offset, n_embd, norm_eps);
}
extern "C" int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!out || !pre || !model_map || n_hc == 0) return 0;
    const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
    if (row_bytes == 0 || out->bytes < row_bytes || out->bytes % row_bytes != 0 ||
        pre->bytes < out->bytes ||
        scale_offset > model_size || sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || row_bytes > model_size - base_offset) {
        return 0;
    }
    const uint64_t n_tokens = out->bytes / row_bytes;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, sizeof(float), "output_hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, row_bytes, "output_hc_base");
    if (!scale || !base) return 0;
    uint64_t n = n_tokens * n_hc;
    output_hc_weights_kernel<<<(n + 255) / 256, 256>>>(
            (float *)out->ptr,
            (const float *)pre->ptr,
            scale,
            base,
            n_hc,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "output hc weights launch");
}
extern "C" int ds4_gpu_hc_expand_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *post, const ds4_gpu_tensor *comb, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !post || !comb || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    (const float *)post->ptr,
                                                    (const float *)comb->ptr,
                                                    n_embd, n_hc, n_tokens,
                                                    n_hc, n_hc * n_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand launch");
}
extern "C" int ds4_gpu_hc_expand_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand_split launch");
}
extern "C" int ds4_gpu_hc_expand_add_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !block_add || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_add->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 1);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split launch");
}
extern "C" int ds4_gpu_shared_down_hc_expand_q8_0_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *shared_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *shared_mid,
        const ds4_gpu_tensor *routed_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, shared_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        shared_mid,
                                                        routed_out,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "shared_down_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(shared_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim,
                                        shared_mid, 1) &&
           ds4_gpu_hc_expand_add_split_tensor(out_hc, shared_out, routed_out,
                                                residual_hc, split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, block_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        x,
                                                        NULL,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "q8_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(block_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim, x, 1) &&
           ds4_gpu_hc_expand_split_tensor(out_hc, block_out, residual_hc,
                                            split, n_embd, n_hc);
}
